func TestMatchRequiresAllConditions(t *testing.T) {
	rule := Rule{
		"id": "R0001", "type": "decision_rule", "condition_logic": "all",
		"conditions": []any{
			Rule{"field": "claim_status", "op": "==", "value": "approved"},
			Rule{"field": "claim_amount", "op": "<=", "value": 5000.0},
		},
		"enforcement_point": "prompt_injection",
	}
	if !RuleMatches(rule, Fact{"claim_status": "approved", "claim_amount": 100.0}) {
		t.Error("金额 100 应命中")
	}
	if RuleMatches(rule, Fact{"claim_status": "approved", "claim_amount": 9999.0}) {
		t.Error("金额 9999 不应命中")
	}
}

