func TestForbiddenPatternScansMessage(t *testing.T) {
	rule := Rule{
		"id":   "R0006",
		"type": "forbidden_pattern",
		"patterns": []any{
			Rule{"kind": "keyword", "expression": "返点"},
			Rule{"kind": "regex", "expression": `\d{11}`},
		},
	}
	if !PatternHitsMessage(rule, "给我点返点吧") {
		t.Error("关键词应命中")
	}
	if !PatternHitsMessage(rule, "我的手机号13800138000") {
		t.Error("正则应命中")
	}
	if PatternHitsMessage(rule, "正常咨询理赔进度") {
		t.Error("正常语句不应命中")
	}
}

